/* @autogenerated */
import { ObservedEmbedRepository } from 'app/features/observe/observed-embed/repository/observed-embed-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';
import { ObservedEmbed } from 'app/features/observe/observed-embed/model/observed-embed.model';
import { Component, inject } from '@angular/core';

@Component({ selector: 'observed-embed-view-enable-action', standalone: false, template: '' })
export class ObservedEmbedViewEnableActionComponent extends ConfirmAction<ObservedEmbed> {
  readonly name = 'enable';
  protected readonly scope = 'observe/observed-embed';
  protected readonly repository = inject(ObservedEmbedRepository);

  protected override appliesTo(items: ObservedEmbed[]) {
    return items.every((item) => !item.enabled) && true;
  }
  protected execute([item]: ObservedEmbed[]) {
    return this.repository.enable(item.uid);
  }
}
